#include <cstdint>
static inline __attribute__((target("popcnt"))) uint32_t
popcount_naive(uint32_t n) {
    return static_cast<uint32_t>(__builtin_popcountll(static_cast<unsigned long long>(n)));
}
#include <cstdint>
#include <cstring>
#include <cmath>
#include <algorithm>
#include <omp.h>
extern "C" __attribute__((target("popcnt"))) void run(const void* input1,const void* input2,void* output,int n,int parameter,int threads)
{const uint32_t*a=(const uint32_t*)input1;uint32_t result=0;for(int j=0;j<parameter;j++)for(int i=0;i<n;i++)result+=popcount_naive(a[i]^result);*(uint32_t*)output=result;}

#include <cstdint>

static inline std::uint32_t popcount_u32(std::uint32_t value) {
    return static_cast<std::uint32_t>(
        __builtin_popcountll(static_cast<unsigned long long>(value)));
}

extern "C" void run(const void* input1, const void* input2, void* output,
                    int n, int parameter, int threads) {
    const std::uint32_t* a = static_cast<const std::uint32_t*>(input1);
    std::uint32_t result = 0;

    for (int j = 0; j < parameter; ++j) {
        int i = 0;
        for (; n - i >= 6; i += 6) {
            result += popcount_u32(a[i] ^ result);
            result += popcount_u32(a[i + 1] ^ result);
            result += popcount_u32(a[i + 2] ^ result);
            result += popcount_u32(a[i + 3] ^ result);
            result += popcount_u32(a[i + 4] ^ result);
            result += popcount_u32(a[i + 5] ^ result);
        }
        for (; i < n; ++i) {
            result += popcount_u32(a[i] ^ result);
        }
    }

    *static_cast<std::uint32_t*>(output) = result;
}
